import React, { useEffect, useState } from 'react';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:4000/api';

function BookingConfirmation({ title, selectedDateLong, selectedTime, bookingData, eventTypeId }) {
  const [status, setStatus] = useState('saving');
  const [error, setError] = useState(null);

  useEffect(() => {
    const saveBooking = async () => {
      try {
        const date = new Date(`${selectedDateLong}, ${selectedTime}`);
        const scheduledAt = date.toISOString();

        const response = await fetch(`${API_BASE}/bookings`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            event_type_id: eventTypeId,
            name: bookingData.name,
            email: bookingData.email,
            notes: bookingData.notes,
            scheduled_at: scheduledAt,
          }),
        });

        if (!response.ok) {
          throw new Error('Could not save booking.');
        }

        setStatus('saved');
      } catch (err) {
        console.error(err);
        setError(err.message);
        setStatus('error');
      }
    };

    if (eventTypeId && bookingData.name && bookingData.email && selectedDateLong && selectedTime) {
      saveBooking();
    } else {
      setError('Missing booking details');
      setStatus('error');
    }
  }, [eventTypeId, bookingData, selectedDateLong, selectedTime]);

  if (status === 'saving') {
    return (
      <div className="booking-page">
        <div className="booking-confirm">
          <h2>Saving booking...</h2>
          <p className="booking-confirm-lead">Please wait.</p>
        </div>
      </div>
    );
  }

  if (status === 'error') {
    return (
      <div className="booking-page">
        <div className="booking-confirm">
          <h2>Booking failed</h2>
          <p className="booking-confirm-lead">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="booking-page">
      <div className="booking-confirm">
        <h2>Confirmed!</h2>
        <p className="booking-confirm-lead">You are scheduled with the host.</p>
        <div className="booking-summary">
          <p>
            <strong>Event:</strong> {title}
          </p>
          <p>
            <strong>When:</strong> {selectedDateLong} at {selectedTime}
          </p>
          <p>
            <strong>Who:</strong> {bookingData.name} ({bookingData.email})
          </p>
          {bookingData.notes ? (
            <p>
              <strong>Notes:</strong> {bookingData.notes}
            </p>
          ) : null}
        </div>
      </div>
    </div>
  );
}

export default BookingConfirmation;
